  CONSTRAINT `fk_Schedule_Team` FOREIGN KEY (`teamId`) REFERENCES `Team` (`id`),
  CONSTRAINT `fk_Schedule_Visitor` FOREIGN KEY (`oppTeamId`) REFERENCES `Team` (`id`)
